package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class CpioArchiveOutputStream_close_TriageGen1Test {

    /**
     * Tests that calling close() on an open stream works correctly.
     * This covers the branch where !this.closed is true.
     */
    @Test
    public void testClose_WhenNotClosed_ShouldCloseSuccessfully() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos)) {
            cos.close();
            // If no exception is thrown, the branch was covered.
        }
    }

    /**
     * Tests that calling close() multiple times does not throw an exception.
     * This covers the branch where !this.closed is false.
     */
    @Test
    public void testClose_WhenAlreadyClosed_ShouldNotThrowException() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos);

        cos.close();
        // Second call should hit the 'if (!this.closed)' check and do nothing
        cos.close();
    }

    /**
     * Tests that close() propagates an IOException if the underlying stream fails.
     * This ensures the super.close() call is exercised and error handling is verified.
     */
    @Test(expected = IOException.class)
    public void testClose_WhenSuperCloseThrowsException_ShouldThrowIOException() throws IOException {
        OutputStream errorStream = new IOExceptionOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(errorStream);

        cos.close();
    }

    /**
     * Mock OutputStream that always throws IOException on close.
     */
    private static class IOExceptionOutputStream extends OutputStream {
        @Override
        public void close() throws IOException {
            throw new IOException("Simulated close failure");
        }

        @Override
        public void write(int b) throws IOException {
            // No-op
        }
    }
}
